            Validate.isTrue(skipped == pos); // Previously asserted that there is room in buf to skip, so this will be a valid check
            bufLength = read;
            readerPos += pos;
            bufPos = 0;
            bufMark = -1;
            bufSplitPoint = bufLength > readAheadLimit ? readAheadLimit : bufLength;
